import{_ as d,o as a,c as r,ag as o}from"./chunks/framework.D5hoimZQ.js";const b=JSON.parse('{"title":"杏林药铺：HTML5 Canvas 中医题材像素风游戏知识总结","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/game-dev/xinglin-pharmacy-game-summary.md","filePath":"topics/game-dev/xinglin-pharmacy-game-summary.md"}'),e={name:"topics/game-dev/xinglin-pharmacy-game-summary.md"};function s(n,t,l,i,h,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="杏林药铺-html5-canvas-中医题材像素风游戏知识总结" tabindex="-1">杏林药铺：HTML5 Canvas 中医题材像素风游戏知识总结 <a class="header-anchor" href="#杏林药铺-html5-canvas-中医题材像素风游戏知识总结" aria-label="Permalink to &quot;杏林药铺：HTML5 Canvas 中医题材像素风游戏知识总结&quot;">​</a></h1><blockquote><p>整理时间：2026-06-16 来源：项目概览文档 + 游戏参考分析</p></blockquote><hr><h2 id="一、项目基本信息" tabindex="-1">一、项目基本信息 <a class="header-anchor" href="#一、项目基本信息" aria-label="Permalink to &quot;一、项目基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>项目名称</strong></td><td>杏林药铺</td></tr><tr><td><strong>文件</strong></td><td><code>index.html</code>（单文件，无需构建，浏览器直接运行）</td></tr><tr><td><strong>配套数据</strong></td><td><code>herbs-data.json</code>（50条药材）/ <code>formulas-data.json</code>（20条经方）/ <code>symptoms-data.json</code>（20条症候）</td></tr><tr><td><strong>技术栈</strong></td><td>HTML5 Canvas，单文件原型</td></tr><tr><td><strong>团队规模</strong></td><td>小团队协作，文件结构简单</td></tr></tbody></table><hr><h2 id="二、核心玩法闭环" tabindex="-1">二、核心玩法闭环 <a class="header-anchor" href="#二、核心玩法闭环" aria-label="Permalink to &quot;二、核心玩法闭环&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>大厅候诊 → 诊断室（望闻问切） → 配药台（选药材≤6味） → 开方 → 结果页（成功/近失/失败）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>环节</th><th>入口函数</th><th>说明</th></tr></thead><tbody><tr><td>大厅候诊</td><td><code>drawHall</code></td><td>随机生成病人，选择接诊</td></tr><tr><td>诊断室</td><td><code>drawDiagnosisRoom</code></td><td>按&quot;望闻问切开方&quot;推进</td></tr><tr><td>配药台</td><td><code>drawCompoundingTable</code></td><td>选药材，匹配经典方剂</td></tr><tr><td>结果页</td><td><code>drawResult</code></td><td>判定是否命中 <code>matchFormula</code></td></tr></tbody></table><hr><h2 id="三、数据结构" tabindex="-1">三、数据结构 <a class="header-anchor" href="#三、数据结构" aria-label="Permalink to &quot;三、数据结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>内容</th></tr></thead><tbody><tr><td><strong>药材</strong></td><td>20味（内嵌数据），另有 <code>herbs-data.json</code> 50条扩展库</td></tr><tr><td><strong>方剂</strong></td><td>12个（内嵌），另有 <code>formulas-data.json</code> 20条经方</td></tr><tr><td><strong>病人</strong></td><td>12个症候（内嵌），另有 <code>symptoms-data.json</code> 20条</td></tr></tbody></table><blockquote><p>三份 JSON <strong>尚未接入游戏</strong>，页面仍在用内嵌精简数据。</p></blockquote><hr><h2 id="四、代码核心模块" tabindex="-1">四、代码核心模块 <a class="header-anchor" href="#四、代码核心模块" aria-label="Permalink to &quot;四、代码核心模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>关键函数</th><th>作用</th></tr></thead><tbody><tr><td>数据定义</td><td>内嵌在 index.html</td><td>药材/方剂/病人数据</td></tr><tr><td>全局状态</td><td><code>state</code> 对象</td><td>场景/库存/当前病人/诊断进度/配伍槽位</td></tr><tr><td>配伍匹配</td><td><code>formulaMatch</code> / <code>bestFormulaMatch</code></td><td>药材集合交并比计算匹配度</td></tr><tr><td>方剂合成</td><td><code>compoundHerbs</code></td><td>完全匹配→解锁经方+奖励金币/声望</td></tr><tr><td>开方治疗</td><td><code>prescribeFormula</code></td><td>按病人目标方剂判断治疗结果</td></tr><tr><td>输入处理</td><td><code>handleClick</code></td><td>所有点击统一入口</td></tr><tr><td>主循环</td><td><code>gameLoop</code></td><td>每帧更新倒计时/粒子/场景渲染</td></tr></tbody></table><hr><h2 id="五、反馈系统" tabindex="-1">五、反馈系统 <a class="header-anchor" href="#五、反馈系统" aria-label="Permalink to &quot;五、反馈系统&quot;">​</a></h2><ul><li>💰 <strong>金币</strong>：配伍成功奖励</li><li>⭐ <strong>声望</strong>：开方正确积累</li><li>💊 <strong>治愈数/失败数</strong>：追踪记录</li><li>⏱️ <strong>急救倒计时</strong>：增加紧迫感</li><li>✨ <strong>粒子特效</strong>：视觉反馈</li><li>🔊 <strong>音效</strong>：听觉反馈</li><li>📜 <strong>卷轴动画</strong>：开方成就感</li></ul><hr><h2 id="六、当前完成度评估" tabindex="-1">六、当前完成度评估 <a class="header-anchor" href="#六、当前完成度评估" aria-label="Permalink to &quot;六、当前完成度评估&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td><strong>玩法闭环</strong></td><td>✅ MVP可玩</td><td>大厅→诊断→配药→开方→结果 已串通</td></tr><tr><td><strong>JSON数据接入</strong></td><td>❌ 未接入</td><td>三份JSON未使用，仍用内嵌数据</td></tr><tr><td><strong>研磨系统</strong></td><td>🔸 半实现</td><td>逻辑已写，UI无研磨按钮</td></tr><tr><td><strong>存档系统</strong></td><td>❌ 无</td><td>刷新即丢失金币/声望/解锁方剂</td></tr><tr><td><strong>模块拆分</strong></td><td>❌ 单文件</td><td><code>data.js</code>/<code>state.js</code>/<code>render.js</code>/<code>game.js</code> 尚未拆分</td></tr><tr><td><strong>难度曲线</strong></td><td>⚠️ 偏弱</td><td>目标方剂直接推荐，诊断引导不够</td></tr><tr><td><strong>解锁系统</strong></td><td>⚠️ 展示为主</td><td>经方标签展示，实质解锁激励不足</td></tr></tbody></table><hr><h2 id="七、改进方向-优先级排序" tabindex="-1">七、改进方向（优先级排序） <a class="header-anchor" href="#七、改进方向-优先级排序" aria-label="Permalink to &quot;七、改进方向（优先级排序）&quot;">​</a></h2><h3 id="高优先级" tabindex="-1">高优先级 <a class="header-anchor" href="#高优先级" aria-label="Permalink to &quot;高优先级&quot;">​</a></h3><ol><li><strong>接入三份 JSON</strong> → 数据驱动，替换内嵌数据</li><li><strong>研磨系统完整实现</strong> → 原药材/粗粉/细粉/极细粉，对应不同药效强度</li><li><strong>localStorage 存档</strong> → 保存金币/声望/解锁方剂/图鉴</li></ol><h3 id="中优先级" tabindex="-1">中优先级 <a class="header-anchor" href="#中优先级" aria-label="Permalink to &quot;中优先级&quot;">​</a></h3><ol start="4"><li><strong>调整诊断难度</strong> → 不直接推荐正确方剂，四诊结果逐步缩小范围</li><li><strong>模块拆分</strong> → <code>data.js</code> + <code>state.js</code> + <code>render.js</code> + <code>game.js</code></li></ol><h3 id="低优先级" tabindex="-1">低优先级 <a class="header-anchor" href="#低优先级" aria-label="Permalink to &quot;低优先级&quot;">​</a></h3><ol start="6"><li><strong>方剂共鸣系统</strong> → 寒+寒=大寒，热+温=温和，类似原神元素反应</li><li><strong>药材产地/时节</strong> → 道地药材品质更高</li><li><strong>病人多样性</strong> → 地域/季节/体质差异</li><li><strong>C端反馈</strong> → 成就系统、病人档案、季节事件</li></ol><hr><h2 id="八、游戏化参考来源" tabindex="-1">八、游戏化参考来源 <a class="header-anchor" href="#八、游戏化参考来源" aria-label="Permalink to &quot;八、游戏化参考来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参考游戏</th><th>借鉴维度</th></tr></thead><tbody><tr><td>Two Point Hospital</td><td>诊断链路迷你小游戏化（脉诊节奏/舌诊颜色匹配）</td></tr><tr><td>Story of Seasons</td><td>病人多样化（地域/季节/体质差异）</td></tr><tr><td><strong>Potion Craft</strong> ⭐</td><td>研磨可视化、方向性操作而非精确匹配</td></tr><tr><td><strong>Genshin Impact</strong> ⭐</td><td>药性共鸣系统（寒/热/温/凉/平组合）</td></tr><tr><td>Little Alchemy</td><td>4基元→组合→发现新组合的惊喜感</td></tr><tr><td>Stardew Valley</td><td>药材图鉴/方剂图鉴/声誉系统/存档</td></tr><tr><td>Moonlighter</td><td>库存管理+声誉定价+每日进货</td></tr><tr><td>不良人/古风游戏</td><td>毛笔字药材/卷轴方剂/古籍风格UI</td></tr></tbody></table><hr><h2 id="九、技术债务清单" tabindex="-1">九、技术债务清单 <a class="header-anchor" href="#九、技术债务清单" aria-label="Permalink to &quot;九、技术债务清单&quot;">​</a></h2><ul><li>[ ] JSON 数据未加载</li><li>[ ] 研磨按钮缺失</li><li>[ ] 刷新存档丢失</li><li>[ ] 单文件过大（1200+行）</li><li>[ ] 无版本控制（建议 git）</li><li>[ ] 无 README/使用说明</li><li>[ ] 无构建流程（无法发布）</li><li>[ ] 无测试用例</li></ul>',36)])])}const m=d(e,[["render",s]]);export{b as __pageData,m as default};
